package site.hsu.hub.application.adapter.out.persistence;import jakarta.persistence.*;import java.time.Instant;
@Entity@Table(name="applications",uniqueConstraints=@UniqueConstraint(columnNames={"user_id","recruitment_id"}))public class ApplicationEntity{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="public_id",nullable=false,unique=true,length=36)private String publicId;@Column(name="user_id",nullable=false)private Long userId;@Column(name="recruitment_id",nullable=false)private Long recruitmentId;@Column(name="submitted_at",nullable=false,updatable=false)private Instant submittedAt;protected ApplicationEntity(){}public ApplicationEntity(String publicId,Long userId,Long recruitmentId){this.publicId=publicId;this.userId=userId;this.recruitmentId=recruitmentId;submittedAt=Instant.now();}public Long id(){return id;}public String publicId(){return publicId;}public Long userId(){return userId;}public Long recruitmentId(){return recruitmentId;}public Instant submittedAt(){return submittedAt;}}
